print(f"Total topics prepared: {len(all_paragraphs)}")

# Generate the dart file
lines = []
lines.append("import '../models/topic_model.dart';")
lines.append("")
lines.append("/// Полный курс биологии 8 класса по официальному учебнику В. В. Пасечника")
lines.append("/// («Линия жизни», Зоология: Животные, Главы 1–8, § 1–60).")
lines.append("/// Каждый параграф вынесен в отдельную самостоятельную тему без объединения.")
lines.append("const List<Topic> biologyTopics8 = [")

for num, title, summary, defs, rules, lifehacks, q, steps, ans, tags in all_paragraphs:
    tid = f"bio_8_p{num:02d}"
    lines.append("  Topic(")
    lines.append(f"    id: '{tid}',")
    lines.append(f"    title: '{title}',")
    lines.append("    subjectId: 'biology',")
    lines.append("    grade: 8,")
    
    # Escape summary
    summary_clean = summary.replace("'", "\\'")
    lines.append(f"    shortSummary:\n        '{summary_clean}',")
    
    # Definitions
    if defs:
        lines.append("    definitions: [")
        for term, d_text in defs:
            t_clean = term.replace("'", "\\'")
            d_clean = d_text.replace("'", "\\'")
            lines.append(f"      DefinitionItem(")
            lines.append(f"        term: '{t_clean}',")
            lines.append(f"        definition: '{d_clean}',")
            lines.append("      ),")
        lines.append("    ],")
        
    # Rules
    if rules:
        lines.append("    rules: [")
        for r in rules:
            r_clean = r.replace("'", "\\'").replace("\n", "\\n")
            lines.append(f"      '{r_clean}',")
        lines.append("    ],")
        
    # Lifehacks
    if lifehacks:
        lines.append("    lifehacks: [")
        for lh in lifehacks:
            lh_clean = lh.replace("'", "\\'")
            lines.append(f"      '{lh_clean}',")
        lines.append("    ],")
        
    # Examples
    lines.append("    examples: [")
    lines.append("      ExampleItem(")
    q_clean = q.replace("'", "\\'")
    lines.append(f"        task: '{q_clean}',")
    lines.append("        steps: [")
    for s in steps:
        s_clean = s.replace("'", "\\'")
        lines.append(f"          '{s_clean}',")
    lines.append("        ],")
    ans_clean = ans.replace("'", "\\'")
    lines.append(f"        answer: '{ans_clean}',")
    lines.append("      ),")
    lines.append("    ],")
    
    # Tags
    tags_str = ", ".join([f"'{t}'" for t in tags])
    lines.append(f"    tags: [{tags_str}],")
    lines.append("  ),")
    lines.append("")

lines.append("];")
lines.append("")

content = "\n".join(lines)

with open(out_file, "w", encoding="utf-8") as f:
    f.write(content)

print(f"Successfully written {len(all_paragraphs)} topics to {out_file} ({len(content)} bytes)!")
